function drawTrend(prs){const groups={};for(const p of prs){const m=Metrics.metrics(p.batches);if(m.e2e_ms==null)continue;const d=date(p.created_ms,true);(groups[d]??=[]).push(m.e2e_ms)}const series=Object.keys(groups).sort().map(d=>({d,...Metrics.stats(groups[d])}));if(!series.length){$('trend').innerHTML='<div class="empty">没有可用于趋势的有效 E2E 样本</div>';return}const W=660,H=196,L=48,R=18,T=14,B=32,max=Math.max(...series.map(s=>s.p90/60000),.01)*1.15;const x=i=>L+(W-L-R)*(series.length===1?.5:i/(series.length-1)),y=v=>T+(H-T-B)*(1-v/60000/max);let svg='';for(let i=0;i<4;i++){const value=max*i/3,yy=y(value*60000);svg+=`<line class="grid-line" x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}"/><text class="axis-text" x="${L-10}" y="${yy+3}" text-anchor="end">${num(value,1)}</text>`}const points=key=>series.map((s,i)=>`${x(i)},${y(s[key])}`).join(' ');svg+=`<polygon class="area-fill" points="${x(0)},${H-B} ${points('mean')} ${x(series.length-1)},${H-B}"/><line class="guide" id="trendGuide" x1="0" x2="0" y1="${T}" y2="${H-B}" visibility="hidden"/><polyline class="p90-line" points="${points('p90')}"/><polyline class="mean-line" points="${points('mean')}"/>`;series.forEach((s,i)=>{svg+=`<circle class="dot" cx="${x(i)}" cy="${y(s.mean)}" r="3"/>`});series.forEach((s,i)=>{if(i===series.length-1||(i%Math.max(1,Math.ceil(series.length/6))===0&&i<series.length-1-Math.ceil(series.length/12)))svg+=`<text class="axis-text" x="${x(i)}" y="${H-9}" text-anchor="middle">${s.d.slice(5)}</text>`});const step=series.length>1?(W-L-R)/(series.length-1):W;svg+=`<rect class="dot-hit" x="${Math.max(0,L-step/2)}" y="${T}" width="${W-R-L+step}" height="${H-T-B}"/><circle class="dot" id="trendHoverDot" r="4.5" visibility="hidden"/>`;$('trend').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="按 PR 创建日期统计的 E2E 平均与 P90 趋势">${svg}</svg><div class="chart-tip" hidden></div>`;const svgEl=$('trend').querySelector('svg'),tip=$('trend').querySelector('.chart-tip'),hoverDot=$('trendHoverDot'),guide=$('trendGuide');svgEl.addEventListener('mousemove',e=>{const r=svgEl.getBoundingClientRect(),px=(e.clientX-r.left)/r.width*W;let i=Math.round((px-L)/step);i=Math.max(0,Math.min(series.length-1,i));const s=series[i],cx=x(i),cy=y(s.mean);hoverDot.setAttribute('cx',cx);hoverDot.setAttribute('cy',cy);hoverDot.setAttribute('visibility','visible');guide.setAttribute('x1',cx);guide.setAttribute('x2',cx);guide.setAttribute('visibility','visible');tip.hidden=false;tip.innerHTML=`${s.d}<br>平均 <b>${minute(s.mean)}</b> · P90 <b>${minute(s.p90)}</b> 分钟<br>n=${s.n}`;const box=$('trend').getBoundingClientRect(),wpx=cx/W*box.width;let left=wpx+12;if(left+160>box.width)left=wpx-172;tip.style.left=Math.max(0,left)+'px';tip.style.top=Math.max(8,cy/H*box.height-14)+'px'});svgEl.addEventListener('mouseleave',()=>{tip.hidden=true;hoverDot.setAttribute('visibility','hidden');guide.setAttribute('visibility','hidden')});}
function drawTasks(s){const field=$('chartMetric').value;const max=Math.max(...['x86','arm','dt'].map(k=>Math.max(s[k][field].p90||0,s[k][field].mean||0)),1)*1.15;$('taskChart').innerHTML=['x86','arm','dt'].map(k=>{const z=s[k][field];return `<div class="task-bar"><div class="task-bar-head"><span>${taskName[k]}</span><small>${minute(z.mean)} / ${minute(z.p90)} <span title="有效样本数">· n=${z.n}</span></small></div><div class="bar-track" title="平均 ${exact(z.mean)} / P90 ${exact(z.p90)}"><div class="bar-fill" style="width:${(z.mean||0)/max*100}%"></div>${z.p90!=null?`<i class="bar-tick" style="left:${z.p90/max*100}%"></i>`:''}</div></div>`}).join('');}
function renderTable(cache){const pages=Math.max(1,Math.ceil(filtered.length/pageSize));page=Math.min(page,pages);const rows=filtered.slice((page-1)*pageSize,page*pageSize),field=$('tableMetric').value;$('prCount').textContent=filtered.length;$('prRows').innerHTML=rows.map(p=>{const s=cache.get(p.number);return `<tr data-pr="${p.number}"><td><button class="pr-title" title="${esc(p.title)}"><b>#${p.number}</b>${esc(p.title)}</button><small class="pr-meta">${date(p.created_ms,true)} · ${esc(p.author)}${p.merged_ms?' · 合入 '+date(p.merged_ms,true):''}</small></td><td>${pill(p.state,stateName)}</td><td>${triggerHTML(p)}</td><td>${resultHTML(p.batches)}${failedHTML(p)}</td><td><div class="metric-value" title="${s.representative_batch_number!=null?'Trigger #'+s.representative_batch_number+' · ':''}${exact(s.e2e_ms)}">${minute(s.e2e_ms)}</div><small class="sample">${s.representative_batch_number!=null?'Trigger #'+s.representative_batch_number:'无有效批次'}</small></td>${['x86','arm','dt'].map(k=>`<td class="num"><div class="metric-value" title="${exact(s[k][field+'_ms'])}">${minute(s[k][field+'_ms'])}</div></td>`).join('')}<td><svg class="icon icon-sm" style="color:var(--text-3)" aria-hidden="true"><use href="#i-chevron-right"/></svg></td></tr>`}).join('')||'<tr><td colspan="9"><div class="empty">当前无匹配 PR，请调整筛选条件。</div></td></tr>';$('prRows').querySelectorAll('tr[data-pr]').forEach(r=>r.onclick=()=>openDetail(Number(r.dataset.pr)));$('pageInfo').textContent=`${page} / ${pages}`;$('prev').disabled=page<=1;$('next').disabled=page>=pages;const label={e2e:'代表 E2E 从长到短；相同 E2E 按创建时间从新到旧',batches:'批次数从多到少；相同批次数按创建时间从新到旧',created:'创建时间从新到旧'};$('rowInfo').textContent=`显示 ${filtered.length?(page-1)*pageSize+1:0}–${Math.min(page*pageSize,filtered.length)} / ${filtered.length} 条 · ${label[$('sort').value]}`;}
