function navigate(hash){const newRoute=Router.parseRoute(hash);if(newRoute){const canonical=Router.formatRoute(newRoute);if(canonical!==location.hash)history.pushState(null,'',canonical);if(newRoute.view==='workbench')applyWorkbenchRoute(newRoute);else applyProjectRoute(newRoute);return;}const raw=String(hash||'').replace(/^#/,'');if(raw.startsWith('projects/')){const parts=raw.split('?')[0].split('/');if(location.hash!=='#'+raw)history.pushState(null,'','#'+raw);unavailableProjectTask({project:parts[1]||'未知项目',task:parts[2]||'未知任务'},'此项目任务未提供或地址无效。');return;}const canonical=Router.resolve(hash);if(canonical!==location.hash){/* REQ-036: 直接目标导航（选择器切仓、返回总览、列表下钻）推进历史，后退逐步回退；仅旧链接或非法格式的规范化替换当前记录，避免多余中间条目。 */if(hash===canonical)history.pushState(null,'',canonical);else history.replaceState(null,'',canonical);}applyRoute(Router.parseHash(canonical));}
