function repositoryState(entry,snap){if(!snap)return entry.status==='failed'?'未获取数据 · 采集失败':'未获取数据 · 待采集';const stale=snap.meta.start_ms!==repositoryIndex.start_ms||snap.meta.end_ms!==repositoryIndex.end_ms;if(stale)return '过期快照 · 不计跨仓汇总';return ({success:'采集完成',partial:'部分采集 · 需关注',failed:'采集失败 · 保留快照',pending:'待采集'})[entry.status]||entry.status;}
