function crossRows(){return Metrics.repositoryRows(repositoryIndex,repositorySnapshots,$('state').value).sort((a,b)=>$('repositorySort').value==='prs'?b.prs.length-a.prs.length:$('repositorySort').value==='name'?a.name.localeCompare(b.name):(b.metrics.e2e.p90??-1)-(a.metrics.e2e.p90??-1));}
