function renderExceptions(prs,repositoryRows){const repoFor=p=>(repositoryRows.find(r=>r.prs.includes(p))||{}).name||'未知仓库',rows=Metrics.sortPRs(prs,'e2e').filter(p=>Metrics.metrics(p.batches).e2e_ms!=null).slice(0,8);$('exceptionRows').innerHTML=rows.length?rows.map(p=>{const m=Metrics.metrics(p.batches),failed=p.batches.filter(b=>b.status==='failure').length,repo=repoFor(p);return `<button class="exception-row" data-repo="${esc(repo)}" data-exception="${p.number}"><span class="exception-repo">${esc(repo)}<small>#${p.number} · ${date(p.created_ms,true)}</small></span><span class="exception-title">${esc(p.title)}<small>${pill(p.state,stateName)}${failed?` · 失败批次 ${failed}`:''}</small></span><span class="exception-e2e">${minute(m.e2e_ms)}<small>E2E · Trigger #${m.representative_batch_number??'—'}</small></span><span class="exception-why">${p.submission_count} 次提交 · ${p.batches.length} 批门禁；点击查看全部批次与任务耗时。</span><svg class="icon icon-sm" aria-hidden="true"><use href="#i-chevron-right"/></svg></button>`}).join(''):'<div class="empty">当前没有可比较的 E2E 样本。</div>';$('exceptionRows').querySelectorAll('[data-exception]').forEach(el=>el.onclick=()=>{currentRepository=el.dataset.repo;navigate('#ubs/repo/'+encodeURIComponent(currentRepository));setTimeout(()=>openDetail(Number(el.dataset.exception)),0);});}
