 try{const file=await Metrics.saveCsv(rows,name,window,meta);const summary=file.metadata?Metrics.exportSummary(file.metadata):'';notice.innerHTML=file.mode==='saved'?'已保存到本地：<a href="'+esc(file.url)+'" download="'+esc(file.name)+'">'+esc(file.name)+' ↓</a>':'已下载：'+esc(file.name)+(summary?'<br><small class="export-meta">'+esc(summary)+'</small>':'');}
