/* UDR-019: versioned public export. Each export scope declares its entity,
   analysis scope, count and unit up front, and binds the release/snapshot
   identity at click time (never after navigation or a snapshot swap). */
function versionedMeta(entity,scope,count,unit){return {entity,scope,count:count==null?null:count,unit:unit||'分钟',duration_unit:'分钟',profile_version:'ubs-pr-representative-v1',snapshot_id:release?.projects?.ubs?.snapshot_version||null,collected_at:snapshot?.meta?.collected_at||repositoryIndex?.generated_at||null,time_basis:release?.projects?.ubs?.window?.time_basis||'pr_created_at'};}
function exportPRs(){const heads=['仓库','PR','标题','状态','作者','创建时间','合入时间','提交次数','全部批次数','创建请求数','推送请求数','重跑请求数','代表trigger编号','代表trigger链接','E2E ms'];for(const k of ['x86','ARM','DT'])for(const f of ['排队','执行','总计'])heads.push(`${k}${f}ms`);const rows=filtered.map(p=>{const s=Metrics.metrics(p.batches),r=[snapshot.meta.repository,p.number,p.title,stateName[p.state],p.author,date(p.created_ms),date(p.merged_ms),p.submission_count,p.batches.length,...['create','push','retest'].map(k=>Metrics.triggerCounts(p)[k]),s.representative_batch_number,s.representative_batch_url,s.e2e_ms];for(const k of ['x86','arm','dt'])for(const f of ['queue','duration','total'])r.push(s[k][f+'_ms']);return r});download([heads,...rows],currentRepository+'-pr-summary.csv',versionedMeta('L 记录（PR）','当前筛选 PR',filtered.length,'分钟'));}
function exportBatches(){if(!detailPR||!detailSnapshot){ensureNotice().textContent='无法导出批次：当前没有打开有效的 PR 详情。';return;}const rows=[['仓库','PR','trigger','E2E结果','触发类型','SHA','请求时间','E2E ms','Jenkins ms','有效E2E批次','用于PR效率汇总','子任务','子任务结果','排队ms','执行ms','总计ms','数据问题']];for(const b of detailPR.batches){for(const j of b.children.length?b.children:[{}])rows.push([detailSnapshot.meta.repository,detailPR.number,b.url,resultName[b.status],kindName[b.event_type]||b.event_type,b.sha,date(b.request_ms),b.e2e_ms,b.jenkins_ms,b.eligible,b.url===Metrics.metrics(detailPR.batches).representative_batch_url,j.url,j.result,j.queue_ms,j.duration_ms,j.total_ms,(b.issues||[]).join('; ')])}download(rows,`${detailRepo}-pr-${detailPR.number}-batches.csv`,versionedMeta('PR 全部批次','PR #'+detailPR.number+' 全部已采集批次',detailPR.batches.length,'分钟'));}
function exportBatchTasks(){if(!detailPR||!detailSnapshot||!detailChoice||!detailChoice.batch){ensureNotice().textContent='无法导出任务：当前没有选中的批次。';return;}const b=detailChoice.batch,tasks=[{...b.trigger,kind:'trigger'},...b.children];const rows=[['仓库','PR','批次','任务类型','任务名称','任务链接','结果','排队ms','执行ms','总计ms']];for(const j of tasks){rows.push([detailSnapshot.meta.repository,detailPR.number,b.number,j.kind==='trigger'?'Trigger':(taskName[j.kind]||j.kind),j.kind==='trigger'?'Trigger':(taskName[j.kind]||j.kind)+' #'+(j.number||b.number),j.url,j.result,j.queue_ms,j.duration_ms,j.total_ms]);}download(rows,`${detailRepo}-pr-${detailPR.number}-batch-${b.number}-tasks.csv`,versionedMeta('选中批次任务','PR #'+detailPR.number+' 选中批次 Trigger #'+b.number,tasks.length,'分钟'));}
/* UDR-019 去重关注：关注按稳定批次身份 (PR::批次) 去重，一个批次一行、
   原因去重合并；采集级问题作为其来源自身的批次身份保留，不并入任意 PR。 */
function exportConcerns(){if(!snapshot)return;const concerns=qualityRows().map(r=>({batch_id:r[0]+'::'+r[1],reason:r[2],pr:r[0],batch:r[1]}));const dedup=QueryState.dedupeConcerns(concerns,c=>c.batch_id,c=>[c.reason]);const rows=[['仓库','PR','批次','原因']];for(const entry of dedup){const it=entry.item;rows.push([snapshot.meta.repository,it.pr,it.batch,entry.reasons.join('; ')]);}download(rows,currentRepository+'-concerns.csv',versionedMeta('去重关注','当前筛选 PR 的数据质量关注（按批次身份去重）',dedup.length,'条'));}
/* A06 (REQ-010): 悬挂或缓慢的请求不得跨域阻塞健康域——UBS 与 Triton 按域提交当前 generation 的结果；每个读取设超时并给出对应提示；代次保护保持不变。 */
const READ_TIMEOUT_MS=30000;
const activeReads=new Set();
function readWithTimeout(p,label,onTimeout){let timer;const timeout=new Promise((_,rej)=>{timer=setTimeout(()=>{rej(Error(label+'读取超时（'+READ_TIMEOUT_MS/1000+' 秒未完成），请检查网络后重新加载'));if(onTimeout)onTimeout();},READ_TIMEOUT_MS)});return Promise.race([p,timeout]).finally(()=>clearTimeout(timer));}
async function readJSON(url,label){
 const controller=new AbortController();activeReads.add(controller);
 const reading=(async()=>{const response=await fetch(url,{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error(label+' HTTP '+response.status);return response.json();})();
 try{return await readWithTimeout(reading,label,()=>controller.abort());}finally{activeReads.delete(controller);}
}
